import React, { useEffect, useState } from 'react';
import '../Estilos/ReservasEspeciales.css';

function ReservasEspeciales() {
  const [error, setError] = useState("");
  const [reservasEspeciales, setReservasEspeciales] = useState([]);
  const [mesesReservados, setMesesReservados] = useState([]);
  const [diasReservados, setDiasReservados] = useState([]);
  const [horasDesdeReservadas, setHorasDesdeReservadas] = useState([]);
  const [horasHastaReservadas, setHorasHastaReservadas] = useState([]);
  const [canchasReservadas, setCanchasReservadas] = useState([]);
  const [equiposReservados, setEquiposReservados] = useState([]);
  const [DEfechasReservadas, setDEfechasReservadas] = useState([]);
  const [DEhorasDesdeReservadas, setDEhorasDesdeReservadas] = useState([]);
  const [DEhorasHastaReservadas, setDEhorasHastaReservadas] = useState([]);
  const [DEcanchasReservadas, setDEcanchasReservadas] = useState([]);
  const [DEequiposReservados, setDEequiposReservados] = useState([]);

  const setErrorWithTimeout = (message) => {
    setError(message);
    setTimeout(() => setError(""), 2000);
  };

  const fetchReservasEspeciales = async () => {
    const token = localStorage.getItem('token');
    if (!token) {
      setErrorWithTimeout('No se encontró el token de autenticación.');
      return;
    }

    try {
      const response = await fetch('http://localhost:5000/get_special_requests', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
      });

      if (response.ok) {
        const data = await response.json();
        setReservasEspeciales(data);
      } else {
        const errorData = await response.json();
        setErrorWithTimeout(errorData.error || 'Error al obtener las reservas especiales.');
      }
    } catch (error) {
      console.error('Error de red:', error);
      setErrorWithTimeout('Error al conectar con el servidor.');
    }
  };

  useEffect(() => {
    fetchReservasEspeciales();
  }, []);

  // Arrays de referencia para ordenar meses y días
  const mesesOrden = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
  const diasOrden = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"];

  const obtenerMeses = () => {
    const mesesReservadosActualizados = reservasEspeciales
      .filter(reserva => reserva.tipo === "DG")
      .map(reserva => Object.keys(reserva.meses)
        .filter(mes => reserva.meses[mes])
        .sort((a, b) => mesesOrden.indexOf(a.toLowerCase()) - mesesOrden.indexOf(b.toLowerCase())) // Ordena los meses
      );

    setMesesReservados(mesesReservadosActualizados);
  };

  const obtenerDias = () => {
    const diasReservadosActualizados = reservasEspeciales
      .filter(reserva => reserva.tipo === "DG")
      .map(reserva => Object.keys(reserva.dias)
        .filter(dia => reserva.dias[dia].seleccionado)
        .sort((a, b) => diasOrden.indexOf(a.toLowerCase()) - diasOrden.indexOf(b.toLowerCase())) // Ordena los días
      );

    setDiasReservados(diasReservadosActualizados);
  };

  const obtenerHoraDesde = () => {
    const horaDesdeActualizados = reservasEspeciales
      .filter(reserva => reserva.tipo === "DG")
      .map(reserva => Object.keys(reserva.dias)
        .filter(dia => reserva.dias[dia].seleccionado)
        .sort((a, b) => diasOrden.indexOf(a.toLowerCase()) - diasOrden.indexOf(b.toLowerCase()))
        .map(dia => reserva.dias[dia].horaDesde)
      );

    setHorasDesdeReservadas(horaDesdeActualizados);
  };

  const obtenerHoraHasta = () => {
    const horaHastaActualizados = reservasEspeciales
      .filter(reserva => reserva.tipo === "DG")
      .map(reserva => Object.keys(reserva.dias)
        .filter(dia => reserva.dias[dia].seleccionado)
        .sort((a, b) => diasOrden.indexOf(a.toLowerCase()) - diasOrden.indexOf(b.toLowerCase()))
        .map(dia => reserva.dias[dia].horaHasta)
      );

    setHorasHastaReservadas(horaHastaActualizados);
  };

  const obtenerCanchas = () => {
    const canchasActualizadas = reservasEspeciales
      .filter(reserva => reserva.tipo === "DG")
      .map(reserva => Object.keys(reserva.dias)
        .filter(dia => reserva.dias[dia].seleccionado)
        .sort((a, b) => diasOrden.indexOf(a.toLowerCase()) - diasOrden.indexOf(b.toLowerCase()))
        .map(dia => reserva.dias[dia].cancha)
      );

    setCanchasReservadas(canchasActualizadas);
  };

  const obtenerEquipos = () => {
    const equiposActualizados = reservasEspeciales
      .filter(reserva => reserva.tipo === "DG")
      .map(reserva => Object.keys(reserva.dias)
        .filter(dia => reserva.dias[dia].seleccionado)
        .sort((a, b) => diasOrden.indexOf(a.toLowerCase()) - diasOrden.indexOf(b.toLowerCase()))
        .map(dia => reserva.dias[dia].equipo)
      );

    setEquiposReservados(equiposActualizados);
  };

  const obtenerFechasDE = () => {
    const fechasActualizadas = reservasEspeciales
      .filter(reserva => reserva.tipo === "DE")
      .map(reserva => reserva.dia_esp.fecha); // Acceso directo a la fecha
  
    setDEfechasReservadas(fechasActualizadas);
  };
  
  const obtenerHoraDesdeDE = () => {
    const hdDEActualizadas = reservasEspeciales
      .filter(reserva => reserva.tipo === "DE")
      .map(reserva => reserva.dia_esp.horaDesde); // Acceso directo a la fecha
  
    setDEhorasDesdeReservadas(hdDEActualizadas);
  };

  const obtenerHoraHastaDE = () => {
    const hhDEActualizadas = reservasEspeciales
      .filter(reserva => reserva.tipo === "DE")
      .map(reserva => reserva.dia_esp.horaHasta); // Acceso directo a la fecha
  
    setDEhorasHastaReservadas(hhDEActualizadas);
  };

  const obtenerCanchasDE = () => {
    const cDEActualizadas = reservasEspeciales
      .filter(reserva => reserva.tipo === "DE")
      .map(reserva => reserva.dia_esp.cancha); // Acceso directo a la fecha
  
    setDEcanchasReservadas(cDEActualizadas);
  };

  const obtenerEquiposDE = () => {
    const eDEActualizadas = reservasEspeciales
      .filter(reserva => reserva.tipo === "DE")
      .map(reserva => reserva.dia_esp.equipo); // Acceso directo a la fecha
  
    setDEequiposReservados(eDEActualizadas);
  };

  const obtenerDatosDG = () => {
    obtenerMeses();
    obtenerDias();
    obtenerHoraDesde();
    obtenerHoraHasta();
    obtenerCanchas();
    obtenerEquipos();
  };

  const obtenerDatosDE = () => {
    obtenerFechasDE();
    obtenerHoraDesdeDE();
    obtenerHoraHastaDE();
    obtenerCanchasDE();
    obtenerEquiposDE();
  };

  useEffect(() => {
    if (reservasEspeciales.length > 0) {
      if (tipoReserva === "DG") obtenerDatosDG();
      else obtenerDatosDE();
    }
  }, [reservasEspeciales, tipoReserva]);

  return (
    <div>
      {error && <div className="error">{error}</div>}

      <h2>Reservas Especiales</h2>
      <div>
        <label>
          Tipo de Reserva:
          <select value={tipoReserva} onChange={(e) => setTipoReserva(e.target.value)}>
            <option value="DG">Días en General</option>
            <option value="DE">Días en Específico</option>
          </select>
        </label>
      </div>

      {tipoReserva === "DG" ? (
        <div className="reservas-list">
          {mesesReservados.map((meses, indexMes) => (
            <div key={indexMes} className="reserva-item">
              <p><strong>Mes:</strong> {meses.join(', ')}</p>
              {diasReservados[indexMes]?.map((dia, indexDia) => (
                <div key={indexDia} className="dia-item">
                  <p><strong>Día:</strong> {dia}</p>
                  <p><strong>Hora Desde:</strong> {horasDesdeReservadas[indexMes]?.[indexDia]}</p>
                  <p><strong>Hora Hasta:</strong> {horasHastaReservadas[indexMes]?.[indexDia]}</p>
                  <p><strong>Cancha:</strong> {canchasReservadas[indexMes]?.[indexDia]}</p>
                  <p><strong>Equipo:</strong> {equiposReservados[indexMes]?.[indexDia]}</p>
                </div>
              ))}
            </div>
          ))}
        </div>
      ) : (
        <div className="reservas-list">
          {DEfechasReservadas.map((fecha, indexFecha) => (
            <div key={indexFecha} className="reserva-item">
              <p><strong>Fecha:</strong> {fecha}</p>
              <p><strong>Hora Desde:</strong> {DEhorasDesdeReservadas[indexFecha]}</p>
              <p><strong>Hora Hasta:</strong> {DEhorasHastaReservadas[indexFecha]}</p>
              <p><strong>Cancha:</strong> {DEcanchasReservadas[indexFecha]}</p>
              <p><strong>Equipo:</strong> {DEequiposReservados[indexFecha]}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default ReservasEspeciales;
